import{_ as o,a0 as p,w as a,s as r,ao as e,I as u,x as t,a1 as i,A as l}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const T=JSON.parse('{"title":"Ubunsys：面向 Ubuntu 资深用户的一个高级系统配置工具 | LCTT x X-CMD","titleTemplate":false,"description":"Ubunsys：面向 Ubuntu 资深用户的一个高级系统配置工具 | LCTT (201807) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Ubunsys：面向 Ubuntu 资深用户的一个高级系统配置工具 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Ubunsys：面向 Ubuntu 资深用户的一个高级系统配置工具 | LCTT (201807) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201807/20170829 An Advanced System Configuration Utility For Ubuntu Power Users","title":"Ubunsys：面向 Ubuntu 资深用户的一个高级系统配置工具","tag":"201807","desc":""},"relativePath":"201807/20170829 An Advanced System Configuration Utility For Ubuntu Power Users.md","filePath":"[post].md"}'),d={name:"201807/20170829 An Advanced System Configuration Utility For Ubuntu Power Users.md"};function b(g,s,y,U,m,w){const n=p("Link");return a(),r("div",null,[s[19]||(s[19]=e(`<h1 id="ubunsys-面向-ubuntu-资深用户的一个高级系统配置工具" tabindex="-1">Ubunsys：面向 Ubuntu 资深用户的一个高级系统配置工具 <a class="header-anchor" href="#ubunsys-面向-ubuntu-资深用户的一个高级系统配置工具" aria-label="Permalink to “Ubunsys：面向 Ubuntu 资深用户的一个高级系统配置工具”">​</a></h1><p><img src="https://www.ostechnix.com/wp-content/uploads/2017/08/Ubunsys-4-1-720x340.png" alt=""></p><p><strong>Ubunsys</strong> 是一个面向 Ubuntu 及其衍生版的基于 Qt 的高级系统工具。高级用户可以使用命令行轻松完成大多数配置。不过为了以防万一某天，你突然不想用命令行了，就可以用 Ubnusys 这个程序来配置你的系统或其衍生系统，如 Linux Mint、Elementary OS 等。Ubunsys 可用来修改系统配置，安装、删除、更新包和旧内核，启用或禁用 <code>sudo</code> 权限，安装主线内核，更新软件安装源，清理垃圾文件，将你的 Ubuntu 系统升级到最新版本等等。以上提到的所有功能都可以通过鼠标点击完成。你不需要再依赖于命令行模式，下面是你能用 Ubunsys 做到的事：</p><ul><li>安装、删除、更新包</li><li>更新和升级软件源</li><li>安装主线内核</li><li>删除旧的和不再使用的内核</li><li>系统整体更新</li><li>将系统升级到下一个可用的版本</li><li>将系统升级到最新的开发版本</li><li>清理系统垃圾文件</li><li>在不输入密码的情况下启用或者禁用 <code>sudo</code> 权限</li><li>当你在终端输入密码时使 <code>sudo</code> 密码可见</li><li>启用或禁用系统休眠</li><li>启用或禁用防火墙</li><li>打开、备份和导入 <code>sources.list.d</code> 和 <code>sudoers</code> 文件</li><li>显示或者隐藏启动项</li><li>启用或禁用登录音效</li><li>配置双启动</li><li>启用或禁用锁屏</li><li>智能系统更新</li><li>使用脚本管理器更新/一次性执行脚本</li><li>从 <code>git</code> 执行常规用户安装脚本</li><li>检查系统完整性和缺失的 GPG 密钥</li><li>修复网络</li><li>修复已破损的包</li><li>还有更多功能在开发中</li></ul><p><strong>重要提示：</strong> Ubunsys 不适用于 Ubuntu 新手。它很危险并且仍然不是稳定版。它可能会使你的系统崩溃。如果你刚接触 Ubuntu 不久，不要使用。但如果你真的很好奇这个应用能做什么，仔细浏览每一个选项，并确定自己能承担风险。在使用这一应用之前记着备份你自己的重要数据。</p><h3 id="安装-ubunsys" tabindex="-1">安装 Ubunsys <a class="header-anchor" href="#安装-ubunsys" aria-label="Permalink to “安装 Ubunsys”">​</a></h3><p>Ubunsys 开发者制作了一个 PPA 来简化安装过程，Ubunsys 现在可以在 Ubuntu 16.04 LTS、 Ubuntu 17.04 64 位版本上使用。</p><p>逐条执行下面的命令，将 Ubunsys 的 PPA 添加进去，并安装它。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo add-apt-repository ppa:adgellida/ubunsys</span></span>
<span class="line"><span>sudo apt-get update</span></span>
<span class="line"><span>sudo apt-get install ubunsys</span></span></code></pre></div>`,9)),u("p",null,[s[1]||(s[1]=t("如果 PPA 无法使用，你可以在",-1)),i(n,{href:"https://github.com/adgellida/ubunsys/releases"},{default:l(()=>[...s[0]||(s[0]=[t("发布页面",-1)])]),_:1}),s[2]||(s[2]=t("根据你自己当前系统，选择正确的安装包，直接下载并安装 Ubunsys。",-1))]),s[20]||(s[20]=e('<h3 id="用途" tabindex="-1">用途 <a class="header-anchor" href="#用途" aria-label="Permalink to “用途”">​</a></h3><p>一旦安装完成，从菜单栏启动 Ubunsys。下图是 Ubunsys 主界面。</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2017/08/Ubunsys-1.png" alt=""></p><p>你可以看到，Ubunsys 有四个主要部分，分别是 Packages、Tweaks、System 和 Repair。在每一个标签项下面都有一个或多个子标签项以对应不同的操作。</p><p><strong>Packages</strong></p><p>这一部分允许你安装、删除和更新包。</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2017/08/Ubunsys-2.png" alt=""></p><p><strong>Tweaks</strong></p><p>在这一部分，我们可以对系统进行多种调整，例如：</p><ul><li>打开、备份和导入 <code>sources.list.d</code> 和 <code>sudoers</code> 文件；</li><li>配置双启动；</li><li>启用或禁用登录音效、防火墙、锁屏、系统休眠、<code>sudo</code> 权限（在不需要密码的情况下）同时你还可以针对某一用户启用或禁用 <code>sudo</code> 权限（在不需要密码的情况下）；</li><li>在终端中输入密码时可见（禁用星号）。</li></ul><p><img src="http://www.ostechnix.com/wp-content/uploads/2017/08/Ubunsys-5.png" alt=""></p><p><strong>System</strong></p><p>这一部分被进一步分成 3 个部分，每个都是针对某一特定用户类型。</p><p><strong>Normal user</strong> 这一标签下的选项可以：</p><ul><li>更新、升级包和软件源</li><li>清理系统</li><li>执行常规用户安装脚本</li></ul><p><strong>Advanced user</strong> 这一标签下的选项可以：</p><ul><li>清理旧的/无用的内核</li><li>安装主线内核</li><li>智能包更新</li><li>升级系统</li></ul><p><strong>Developer</strong> 这一部分可以将系统升级到最新的开发版本。</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2017/08/Ubunsys-9.png" alt=""></p><p><strong>Repair</strong></p><p>这是 Ubunsys 的第四个也是最后一个部分。正如名字所示，这一部分能让我们修复我们的系统、网络、缺失的 GPG 密钥，和已经缺失的包。</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2017/08/Ubunsys-11.png" alt=""></p><p>正如你所见，Ubunsys 可以在几次点击下就能完成诸如系统配置、系统维护和软件维护之类的任务。你不需要一直依赖于终端。Ubunsys 能帮你完成任何高级任务。再次声明，我警告你，这个应用不适合新手，而且它并不稳定。所以当你使用的时候，能会出现 bug 或者系统崩溃。在仔细研究过每一个选项的影响之后再使用它。</p><p>谢谢阅读！</p><h3 id="参考资源" tabindex="-1">参考资源 <a class="header-anchor" href="#参考资源" aria-label="Permalink to “参考资源”">​</a></h3>',25)),u("ul",null,[u("li",null,[i(n,{href:"https://github.com/adgellida/ubunsys"},{default:l(()=>[...s[3]||(s[3]=[t("Ubunsys GitHub Repository",-1)])]),_:1})])]),s[21]||(s[21]=u("hr",null,null,-1)),u("p",null,[s[5]||(s[5]=t("via: ",-1)),i(n,{href:"https://www.ostechnix.com/ubunsys-advanced-system-configuration-utility-ubuntu-power-users/"},{default:l(()=>[...s[4]||(s[4]=[t("https://www.ostechnix.com/ubunsys-advanced-system-configuration-utility-ubuntu-power-users/",-1)])]),_:1})]),u("p",null,[s[10]||(s[10]=t("作者：",-1)),i(n,{href:"https://www.ostechnix.com/author/sk/"},{default:l(()=>[...s[6]||(s[6]=[t("SK",-1)])]),_:1}),s[11]||(s[11]=t(" 选题：",-1)),i(n,{href:"https://github.com/lujun9972"},{default:l(()=>[...s[7]||(s[7]=[t("lujun9972",-1)])]),_:1}),s[12]||(s[12]=t(" 译者：",-1)),i(n,{href:"https://github.com/wenwensnow"},{default:l(()=>[...s[8]||(s[8]=[t("wenwensnow",-1)])]),_:1}),s[13]||(s[13]=t(" 校对：",-1)),i(n,{href:"https://github.com/wxy"},{default:l(()=>[...s[9]||(s[9]=[t("wxy",-1)])]),_:1})]),u("p",null,[s[16]||(s[16]=t("本文由 ",-1)),i(n,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...s[14]||(s[14]=[t("LCTT",-1)])]),_:1}),s[17]||(s[17]=t(" 原创编译，",-1)),i(n,{href:"https://linux.cn/"},{default:l(()=>[...s[15]||(s[15]=[t("Linux中国",-1)])]),_:1}),s[18]||(s[18]=t(" 荣誉推出",-1))])])}const x=o(d,[["render",b]]);export{T as __pageData,x as default};
